        } else if (strcmp(command, "GRN") == 0) {
            int x, y, r;
            scanf("%d %d %d", &x, &y, &r);

            int killed = 0;
            int kill_indices[MAX_INVADERS];

            for (int i = 0; i < invader_count; i++) {
                if (invaders[i].active) {
                    int dx = invaders[i].x - x;
                    int dy = invaders[i].y - y;
