#define MAXN 100005

int pos[MAXN];
int alive[MAXN];
int n = 0;

int main() {
    int q;
    scanf("%d", &q);

    while (q--) {
        char type[5];
        scanf("%s", type);

        if (type[0] == 'A') {
            int x;
            scanf("%d", &x);
            pos[n] = x;
            alive[n] = 1;
            n++;
        } else if (type[0] == 'M') {
            int id, dx;
            scanf("%d %d", &id, &dx);
            if (alive[id]) pos[id] += dx;
        } else if (type[0] == 'S') {
            int x;
            scanf("%d", &x);
            for (int i = 0; i < n; i++) {
                if (alive[i] && pos[i] == x) {
                    alive[i] = 0;
                    break;
                }
            }
        } else if (type[0] == 'G') {
            int x, r;
            scanf("%d %d", &x, &r);
            for (int i = 0; i < n; i++) {
                if (alive[i] && abs(pos[i] - x) <= r) {
                    alive[i] = 0;
                }
            }
        } else if (type[0] == 'Q') {
            int cnt = 0;
            for (int i = 0; i < n; i++) if (alive[i]) cnt++;
            printf("%d\n", cnt);
        }
    }
    return 0;
