typedef long long ll;

typedef struct {
    ll x;
    ll hp;
} Alien;

typedef struct {
    Alien *a;
    int n, cap;
} Vec;

static void vec_init(Vec *v) {
    v->n = 0;
    v->cap = 8;
    v->a = (Alien*)malloc(sizeof(Alien) * v->cap);
}

static void vec_push(Vec *v, ll x, ll hp) {
    if (v->n == v->cap) {
        v->cap <<= 1;
        v->a = (Alien*)realloc(v->a, sizeof(Alien) * v->cap);
    }
    v->a[v->n].x = x;
    v->a[v->n].hp = hp;
    v->n++;
}

static int cmp_alien(const void *p1, const void *p2) {
    const Alien *a = (const Alien*)p1;
    const Alien *b = (const Alien*)p2;
    if (a->x < b->x) return -1;
    if (a->x > b->x) return 1;
    return 0;
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    Vec aliens;
    vec_init(&aliens);

    /*
      Since the exact statement/query format is not available in the prompt,
      this solution supports a common simple format:
        1 x h   -> add invader at position x with health h
        2 d     -> move all invaders by -d (towards base)
        3 p     -> sniper attack at exact position p, damage 1 to first alive there
        4 l r g -> grenade attack on interval [l, r], damage g to all there
      At the end, print all alive invaders sorted by position:
        count
        x hp
        ...

      If input differs, this code may need adaptation to the original statement.
    */

    for (int i = 0; i < q; i++) {
        int type;
        if (scanf("%d", &type) != 1) break;

        if (type == 1) {
            ll x, h;
            scanf("%lld %lld", &x, &h);
            vec_push(&aliens, x, h);
        } else if (type == 2) {
            ll d;
            scanf("%lld", &d);
            for (int j = 0; j < aliens.n; j++) {
                if (aliens.a[j].hp > 0) aliens.a[j].x -= d;
            }
        } else if (type == 3) {
            ll p;
            scanf("%lld", &p);
            for (int j = 0; j < aliens.n; j++) {
                if (aliens.a[j].hp > 0 && aliens.a[j].x == p) {
                    aliens.a[j].hp--;
                    break;
                }
            }
        } else if (type == 4) {
            ll l, r, g;
            scanf("%lld %lld %lld", &l, &r, &g);
            for (int j = 0; j < aliens.n; j++) {
                if (aliens.a[j].hp > 0 && l <= aliens.a[j].x && aliens.a[j].x <= r) {
                    aliens.a[j].hp -= g;
                }
            }
        }
    }

    qsort(aliens.a, aliens.n, sizeof(Alien), cmp_alien);

    int alive = 0;
    for (int i = 0; i < aliens.n; i++) {
        if (aliens.a[i].hp > 0) alive++;
    }

    printf("%d\n", alive);
    for (int i = 0; i < aliens.n; i++) {
        if (aliens.a[i].hp > 0) {
            printf("%lld %lld\n", aliens.a[i].x, aliens.a[i].hp);
        }
    }

    free(aliens.a);
    return 0;
}

