                killed += it->second;
                it = invaders.erase(it);
            }
            cout << killed << "\n";
        } else if (op == "COUNT") {
            int total = 0;
            for (auto& p : invaders) total += p.second;
            cout << total << "\n";
        }
    }

    return 0;
