import java.io.*;
import java.util.*;

public class Solution {
    static class Invader {
        int id;
        int x, y;

        Invader(int id, int x, int y) {
            this.id = id;
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        Map<Integer, Invader> invaders = new HashMap<>();
        Map<String, Set<Integer>> positionMap = new HashMap<>();

        String line;
        int queryCount = 0;

        while ((line = br.readLine()) != null && !line.isEmpty()) {
            String[] parts = line.split(" ");
            String type = parts[0];

            switch(type) {
                case "ADD":
                    int id = Integer.parseInt(parts[1]);
                    int x = Integer.parseInt(parts[2]);
                    int y = Integer.parseInt(parts[3]);

                    if (!invaders.containsKey(id)) {
                        Invader inv = new Invader(id, x, y);
                        invaders.put(id, inv);
                        String key = x + "," + y;
                        positionMap.computeIfAbsent(key, k -> new HashSet<>()).add(id);
                        pw.println("ADDED " + id);
                    } else {
                        pw.println("ID_EXISTS " + id);
                    }
                    break;

                case "MOVE":
                    int moveId = Integer.parseInt(parts[1]);
                    int newX = Integer.parseInt(parts[2]);
                    int newY = Integer.parseInt(parts[3]);

                    if (invaders.containsKey(moveId)) {
                        Invader inv = invaders.get(moveId);
                        String oldKey = inv.x + "," + inv.y;
                        positionMap.get(oldKey).remove(moveId);
                        if (positionMap.get(oldKey).isEmpty()) {
                            positionMap.remove(oldKey);
                        }

                        inv.x = newX;
                        inv.y = newY;
                        String newKey = newX + "," + newY;
                        positionMap.computeIfAbsent(newKey, k -> new HashSet<>()).add(moveId);
                        pw.println("MOVED " + moveId);
                    } else {
                        pw.println("NOT_FOUND " + moveId);
                    }
                    break;

                case "SNIPER":
                    int sniperX = Integer.parseInt(parts[1]);
                    int sniperY = Integer.parseInt(parts[2]);
                    String sniperKey = sniperX + "," + sniperY;

                    if (positionMap.containsKey(sniperKey)) {
                        Set<Integer> ids = positionMap.get(sniperKey);
                        int killedId = ids.iterator().next();
                        ids.remove(killedId);
                        if (ids.isEmpty()) {
                            positionMap.remove(sniperKey);
                        }
                        invaders.remove(killedId);
                        pw.println("KILLED " + killedId);
                    } else {
                        pw.println("NO_TARGET");
                    }
                    break;

                case "GRENADE":
                    int grenadeX = Integer.parseInt(parts[1]);
                    int grenadeY = Integer.parseInt(parts[2]);
                    int radius = Integer.parseInt(parts[3]);

                    List<Integer> killedIds = new ArrayList<>();
                    for (Map.Entry<String, Set<Integer>> entry : positionMap.entrySet()) {
                        String[] coords = entry.getKey().split(",");
                        int invX = Integer.parseInt(coords[0]);
                        int invY = Integer.parseInt(coords[1]);

                        int dx = Math.abs(invX - grenadeX);
                        int dy = Math.abs(invY - grenadeY);

                        if (dx <= radius && dy <= radius) {
                            killedIds.addAll(entry.getValue());
                        }
                    }

                    for (int killedId : killedIds) {
                        Invader inv = invaders.get(killedId);
                        String key = inv.x + "," + inv.y;
                        positionMap.get(key).remove(killedId);
                        if (positionMap.get(key).isEmpty()) {
                            positionMap.remove(key);
                        }
                        invaders.remove(killedId);
                    }

                    if (killedIds.isEmpty()) {
                        pw.println("NO_TARGET");
                    } else {
                        Collections.sort(killedIds);
                        StringBuilder sb = new StringBuilder("KILLED");
                        for (int killedId : killedIds) {
                            sb.append(" ").append(killedId);
                        }
                        pw.println(sb.toString());
                    }
                    break;
            }
            queryCount++;
        }

        pw.flush();
        pw.close();
        br.close();
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int n = Integer.parseInt(br.readLine().trim());

        // Map from invader id to position
        Map<Integer, int[]> invaders = new HashMap<>();
        // Grid to track invaders at each position
        Map<String, Set<Integer>> grid = new HashMap<>();

        for (int q = 0; q < n; q++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            String type = st.nextToken();

            if (type.equals("ADD")) {
                int id = Integer.parseInt(st.nextToken());
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                invaders.put(id, new int[]{x, y});
                String key = x + "," + y;
                grid.computeIfAbsent(key, k -> new HashSet<>()).add(id);
            } else if (type.equals("MOVE")) {
                int id = Integer.parseInt(st.nextToken());
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                if (invaders.containsKey(id)) {
                    int[] pos = invaders.get(id);
                    String oldKey = pos[0] + "," + pos[1];
                    if (grid.containsKey(oldKey)) {
                        grid.get(oldKey).remove(id);
                    }
                    invaders.put(id, new int[]{x, y});
                    String newKey = x + "," + y;
                    grid.computeIfAbsent(newKey, k -> new HashSet<>()).add(id);
                }
            } else if (type.equals("SNIPER")) {
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                String key = x + "," + y;
                Set<Integer> at = grid.getOrDefault(key, new HashSet<>());
                int count = at.size();
                List<Integer> toRemove = new ArrayList<>(at);
                for (int id : toRemove) {
                    invaders.remove(id);
                }
                at.clear();
                sb.append(count).append("\n");
            } else if (type.equals("GRENADE")) {
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                int r = Integer.parseInt(st.nextToken());
                int count = 0;
                List<String> keysToProcess = new ArrayList<>(grid.keySet());
                for (String key : keysToProcess) {
                    String[] parts = key.split(",");
                    int gx = Integer.parseInt(parts[0]);
                    int gy = Integer.parseInt(parts[1]);
                    int dist = Math.abs(gx - x) + Math.abs(gy - y);
                    if (dist <= r) {
                        Set<Integer> at = grid.get(key);
                        count += at.size();
                        for (int id : at) {
                            invaders.remove(id);
                        }
                        at.clear();
                    }
                }
                sb.append(count).append("\n");
            } else if (type.equals("COUNT")) {
                sb.append(invaders.size()).append("\n");
            }
        }

        System.out.print(sb);
    }
}

